package shared

import (
	"path/filepath"
	"regexp"
	"strings"
)

// generatedHeaderBytes bounds how much of a file is inspected for a
// generated-code marker. Markers live in the header by convention.
const generatedHeaderBytes = 4096

// goGeneratedRe is the Go convention: https://go.dev/s/generatedcode
var goGeneratedRe = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.$`)

// commentMarkerRe matches the Meta/Relay "@generated" and .NET
// "<auto-generated>" markers only at the start of a comment line, so code that
// merely mentions a marker is not mistaken for generated output.
var commentMarkerRe = regexp.MustCompile(`(?m)^\s*(?://+|/\*+|\*|#)\s*(?:@generated\b|<auto-generated)`)

// IsGeneratedSource reports whether file content carries a generated-code
// marker. Generated code is not refactored by hand, so directory walks skip it.
func IsGeneratedSource(data []byte) bool {
	head := data
	if len(head) > generatedHeaderBytes {
		head = head[:generatedHeaderBytes]
	}
	if goGeneratedRe.Match(head) {
		return true
	}
	return commentMarkerRe.Match(head)
}

// IsGeneratedName reports whether a file name alone marks it as build output
// or a declaration stub rather than hand-written source.
func IsGeneratedName(path string) bool {
	base := strings.ToLower(filepath.Base(path))
	for _, suffix := range []string{".min.js", ".bundle.js", ".d.ts", ".pb.go"} {
		if strings.HasSuffix(base, suffix) {
			return base != suffix
		}
	}
	return false
}
